<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import AppIcon from '@/components/AppIcon.vue'
import ApiWorkspace from '@/components/ApiWorkspace.vue'
import { accountState } from '@/services/officine'
import SidebarNavigation from '@/components/SidebarNavigation.vue'
import { navigation, plannedTitle } from '@/config/navigation'
import { demoMode, request, resetDemo } from '@/services/quality'
const route=useRoute();const router=useRouter();const menu=ref(false)
let stored=false;try{stored=localStorage.getItem('bestpharma.sidebar.collapsed')==='true'}catch{/* optional preference */}
const collapsed=ref(stored);const resetOpen=ref(false);const resetError=ref('');const searchOpen=ref(false);const search=ref('')
const validationMode=import.meta.env.VITE_VALIDATION_MODE==='true'
const publicPage=computed(()=>route.meta.public)
const canReview=computed(()=>{void route.path;return demoMode||sessionStorage.getItem('bestpharma.platform')==='true'})
const pageTitle=computed(()=>route.meta.title==='Module prévu'?plannedTitle(route.fullPath):route.meta.title)
const results=computed(()=>navigation.flatMap(g=>g.children.map(c=>({...c,group:g.label}))).filter(c=>c.label.toLocaleLowerCase('fr').includes(search.value.toLocaleLowerCase('fr'))))
function toggleCollapse(){collapsed.value=!collapsed.value;try{localStorage.setItem('bestpharma.sidebar.collapsed',String(collapsed.value))}catch{/* optional preference */}}
function reset(){resetError.value='';resetOpen.value=true}
function confirmReset(){try{resetDemo();window.location.assign('/dashboard')}catch{resetError.value='Impossible de réinitialiser les données locales.'}}
async function logout(){try{if(!demoMode)await request('/auth/logout','POST')}finally{accountState.user=null;accountState.officines=[];sessionStorage.removeItem('bestpharma.token');sessionStorage.removeItem('bestpharma.officine');sessionStorage.removeItem('bestpharma.platform');router.push('/login')}}
</script>
<template><RouterView v-if="publicPage"/><div v-else class="app-shell erp-shell" :class="{'sidebar-collapsed':collapsed}"><a class="skip-link" href="#main">Aller au contenu</a><aside class="sidebar" :class="{expanded:menu}"><div class="sidebar-brand"><RouterLink to="/dashboard" class="brand" @click="menu=false"><span class="brand-mark">b<span>+</span></span><span class="brand-word">bestpharma<span class="brand-dot">.</span></span></RouterLink><button class="icon-button collapse-control" :aria-label="collapsed?'Déplier la barre latérale':'Replier la barre latérale'" :aria-expanded="!collapsed" @click="toggleCollapse"><AppIcon name="chevron" :size="15" :style="{transform:collapsed?'':'rotate(180deg)'}"/></button></div>
<ApiWorkspace v-if="!demoMode"/><RouterLink v-else to="/dashboard/officine" class="workspace" title="Paramètres Officine" @click="menu=false"><div class="workspace-avatar">BP</div><div class="workspace-copy"><strong>{{demoMode?'Espace de démonstration':'Espace officine'}}</strong><small>{{demoMode?'Découvrir BestPharma':'Session API'}}</small></div><AppIcon name="chevron" :size="13"/></RouterLink>
<SidebarNavigation :collapsed="collapsed&&!menu" @navigate="menu=false" @expand="collapsed=false"/>
<div class="sidebar-admin"><RouterLink v-if="!demoMode&&accountState.user?.is_support_coordinator" class="nav-item" to="/beg/demandes-accompagnement" title="Guichet accompagnement" @click="menu=false"><AppIcon name="support" :size="17"/><span>Guichet accompagnement</span></RouterLink><RouterLink v-if="!demoMode" class="nav-item" to="/dashboard/acces" title="Tableau des accès"><AppIcon name="team" :size="17"/><span>Tableau des accès</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/synthese" title="Synthèse plateforme"><AppIcon name="quality" :size="17"/><span>Synthèse plateforme</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/comptes" title="État des comptes"><AppIcon name="team" :size="17"/><span>État des comptes</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/equipe-interne" title="Équipe interne"><AppIcon name="team" :size="17"/><span>Équipe d’accompagnement</span></RouterLink><RouterLink v-if="canReview&&!demoMode" class="nav-item" to="/beg/officines" title="États des officines"><AppIcon name="settings" :size="17"/><span>États des officines</span></RouterLink><RouterLink v-if="!demoMode&&accountState.user?.is_support_coordinator" class="nav-item" to="/beg/accompagnateurs" title="Coordination des accès" @click="menu=false"><AppIcon name="support" :size="17"/><span>Coordination des accès</span></RouterLink><RouterLink to="/application" class="nav-item" title="Mon dossier d’ouverture" @click="menu=false"><AppIcon name="documents" :size="17"/><span>Mon dossier d’ouverture</span></RouterLink><RouterLink v-if="canReview" to="/beg/inscriptions" class="nav-item" title="Instruction BEG" @click="menu=false"><AppIcon name="quality" :size="17"/><span>Instruction BEG <small v-if="demoMode">DÉMO</small></span></RouterLink></div>
<div class="sidebar-bottom"><button class="profile" @click="logout" title="Quitter la session"><span class="profile-avatar">{{demoMode?'AD':'M'}}</span><span class="profile-copy"><strong>{{demoMode?'Alex Démo':'Mon compte'}}</strong><small>{{demoMode?'Session fictive · Quitter':'Quitter la session'}}</small></span><AppIcon name="logout" :size="16"/></button></div></aside>
<button v-if="menu" class="menu-overlay" aria-label="Fermer le menu" @click="menu=false"/>
<div class="workspace-main"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-menu" aria-label="Ouvrir le menu" :aria-expanded="menu" @click="menu=!menu"><AppIcon name="menu"/></button><span class="breadcrumb-root">Espace officine</span><AppIcon class="breadcrumb-root" name="chevron" :size="12"/><strong>{{pageTitle}}</strong></div><div class="topbar-right"><RouterLink v-if="!demoMode" to="/notifications" class="icon-button" aria-label="Notifications"><AppIcon name="info" :size="17"/></RouterLink><button class="header-search" @click="search='';searchOpen=true"><AppIcon name="search" :size="16"/><span>Rechercher un espace…</span></button><span class="environment"><i/>{{demoMode?'Démo locale':'Mode API'}}</span><RouterLink to="/dashboard/profil" class="top-avatar" aria-label="Mon profil">{{demoMode?'AD':'M'}}</RouterLink></div></header>
<div v-if="demoMode||validationMode" class="demo-banner"><AppIcon name="info" :size="15"/><span>{{demoMode?'Données fictives · aucune donnée personnelle ou de santé. Modules 01 & 02 à explorer depuis le menu.':'Validation API + PostgreSQL · données fictives uniquement. Module 01 connecté. Le module 02 reste en démonstration séparée.'}}</span><button v-if="demoMode" class="reset-demo" @click="reset">Réinitialiser la qualité</button></div>
<main id="main" tabindex="-1"><RouterView/></main><footer>BestPharma · L’officine, accompagnée.<span>Outil interne — ne vaut pas certification ABMed.</span></footer></div></div>
<AppModal v-model="resetOpen" title="Réinitialiser les actions fictives ?" size="small"><div class="form-body"><p v-if="resetError" class="alert error" role="alert">{{resetError}}</p><p>Les actions qualité seront restaurées. Les dossiers, l’équipe et les exemples des modules 01 & 02 ne seront pas modifiés.</p></div><template #footer><button class="button secondary" @click="resetOpen=false">Annuler</button><button class="button primary" @click="confirmReset">Réinitialiser les actions</button></template></AppModal>
<AppModal v-model="searchOpen" title="Rechercher un espace"><div class="form-body"><label class="search-field"><AppIcon name="search" :size="17"/><input v-model="search" placeholder="Ex. accompagnement, stock…" aria-label="Rechercher un espace"/></label><ul class="search-results"><li v-for="r in results" :key="r.to"><RouterLink :to="r.to" @click="searchOpen=false"><span>{{r.label}}<small>{{r.group}}</small></span><span v-if="r.planned" class="module-chip">À venir</span><AppIcon v-else name="chevron" :size="14"/></RouterLink></li></ul><p v-if="!results.length" class="empty-state">Aucun espace correspondant.</p></div></AppModal></template>
